const body  = $input.item.json.body || $input.item.json;
const cfg   = $('⚙️ CONFIG Lead Premium').first().json;

const email     = (body.email || '').trim().toLowerCase();
const firstName = (body.first_name || body.firstName || body.nombre || '').trim();
const phone     = (body.phone || body.telefono || '').trim();
const blogId    = String(body.blog_id || body.blogId || '').trim();
const blogName  = (body.blog_name || body.blogName || '').trim();
const leadValue = parseFloat(body.lead_value || body.leadValue || cfg.LEAD_VALUE_DEFAULT);

if (!email) {
  return { json: { _error: 'Email requerido', received: body } };
}

return { json: {
  email, firstName, phone, blogId, blogName, leadValue,
  timestamp: new Date().toISOString(),
  SHEET_ID:   cfg.SHEET_ID,
  HOJA_BLOGS: cfg.HOJA_BLOGS
}};

const leadData  = $('🔍 Extraer Datos del Lead').first().json;
const sheetRows = $input.all().map(i => i.json);

let matchRow = null;

// Buscar por BLOG_ID exacto primero
if (leadData.blogId) {
  matchRow = sheetRows.find(r => String(r.BLOG_ID).trim() === leadData.blogId);
}

// Fallback: buscar por nombre del blog (case-insensitive partial)
if (!matchRow && leadData.blogName) {
  const bn = leadData.blogName.toLowerCase();
  matchRow = sheetRows.find(r =>
    (r.BLOG_NAME || '').toLowerCase().includes(bn) ||
    bn.includes((r.BLOG_NAME || '').toLowerCase())
  );
}

if (!matchRow) {
  return [{ json: {
    _noMatch: true,
    message: `No se encontró blog para blog_id=${leadData.blogId} / blog_name=${leadData.blogName}`,
    leadData
  }}];
}

const currentTotal = parseInt(matchRow.LEADS_PREMIUM_TOTAL || 0);

return [{ json: {
  _noMatch: false,
  rowNumber: matchRow._rowNumber,
  BLOG_NAME: matchRow.BLOG_NAME,
  BLOG_ID:   matchRow.BLOG_ID,
  newTotal:  currentTotal + 1,
  ...leadData
}}];
